 >> 4) & 0xF\n    z2 = (z_packed >> 8) & 0xF\n    z3 = (z_packed >> 12) & 0xF\n    z4 = (z_packed >> 16) & 0xF\n    z5 = (z_packed >> 20) & 0xF\n    z6 = (z_packed >> 24) & 0xF\n    z7 = (z_packed >> 28) & 0xF\n\n    zlow_2_0 = tl.interleave(z0, z2)\n    zlow_2_1 = tl.interleave(z1, z3)\n    zlow_4 = tl.interleave(zlow_2_0, zlow_2_1)\n    zhigh_2_0 = tl.interleave(z4, z6)\n    zhigh_2_1 = tl.interleave(z5, z7)\n    zhigh_4 = tl.interleave(zhigh_2_0, zhigh_2_1)\n    zeros = tl.interleave(zlow_4, zhigh_4)\n\n    s_x = pid_x * BLOCK_SIZE_X * 8 + tl.arange(0, BLOCK_SIZE_X * 8)\n    s_offsets = (num_cols * 8) * z_y[:, None] + s_x[None, :]\n    s_mask = (z_y[:, None] < num_rows // group_size) & (s_x[None, :] < num_cols * 8)\n    scales = tl.load(scales_ptr + s_offsets, mask=s_mask)\n\n    iweights = (iweights - zeros) * scales\n    iweights = iweights.to(result_ptr.type.element_ty)\n\n    res_x = pid_x * BLOCK_SIZE_X * 8 + tl.arange(0, BLOCK_SIZE_X * 8)\n    res_offsets = (num_cols * 8) * offsets_y[:, None] + res_x[None, :]\n    res_mask = (offsets_y[:, None] < num_rows) & (res_x[None, :] < num_cols * 8)\n    tl.store(result_ptr + res_offsets, iweights, mask=res_mask)",
        "awq_gemm_kernel": "@triton.jit\ndef awq_gemm_kernel(a_ptr, b_ptr, c_ptr, zeros_ptr, scales_ptr, M, N, K,\n                    group_size, BLOCK_SIZE_M: tl.constexpr,\n                    BLOCK_SIZE_N: tl.constexpr, BLOCK_SIZE_K: tl.constexpr,\n                    SPLIT_K: tl.constexpr):\n    pid = tl.program_id(axis=0)\n    pid_z = tl.program_id(1)\n\n    num_pid_n = tl.cdiv(N, BLOCK_SIZE_N)\n    pid_m = pid // num_pid_n\n    pid_n = pid % num_pid_n\n\n    accumulator_dtype = c_ptr.type.element_ty\n    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N),\n                           dtype=accumulator_dtype)\n\n    # Offsets and masks.\n    offsets_am = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)\n    masks_am = offsets_am < M\n\n    offsets_bn = pid_n * (BLOCK_SIZE_N // 8) + tl.arange(0, BLOCK_SIZE_N // 8)\n    masks_bn = offsets_bn < N // 8\n\n    offsets_k = pid_z * BLOCK_SIZE_K + tl.arange(0, BLOCK_SIZE_K)\n\n    a_ptrs = a_ptr + (pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M))[:, None] * K + (pid_z * BLOCK_SIZE_K + tl.arange(0, BLOCK_SIZE_K))[None, :]\n    b_ptrs = b_ptr + (pid_z * BLOCK_SIZE_K + tl.arange(0, BLOCK_SIZE_K))[:, None] * (N // 8) + (pid_n * (BLOCK_SIZE_N // 8) + tl.arange(0, BLOCK_SIZE_N // 8))[None, :]\n\n    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K * SPLIT_K)):\n        curr_offsets_k = offsets_k + k * BLOCK_SIZE_K * SPLIT_K\n        masks_k = curr_offsets_k < K\n\n        a = tl.load(a_ptrs, mask=masks_am[:, None] & masks_k[None, :])\n        b_packed = tl.load(b_ptrs, mask=masks_k[:, None] & masks_bn[None, :])\n\n        # Unpack b_packed\n        w0 = (b_packed >> 0) & 0xF\n        w1 = (b_packed >> 4) & 0xF\n        w2 = (b_packed >> 8) & 0xF\n        w3 = (b_packed >> 12) & 0xF\n        w4 = (b_packed >> 16) & 0xF\n        w5 = (b_packed >> 20) & 0xF\n        w6 = (b_packed >> 24) & 0xF\n        w7 = (b_packed >> 28) & 0xF\n\n        low_2_0 = tl.interleave(w0, w2)\n        low_2_1 = tl.interleave(w1, w3)\n        low_4 = tl.interleave(low_2_0, low_2_1)\n        high_2_0 = tl.interleave(w4, w6)\n        high_2_1 = tl.interleave(w5, w7)\n        high_4 = tl.interleave(high_2_0, high_2_1)\n        b = tl.interleave(low_4, high_4)\n\n        # Dequantize b.\n        z_k = curr_offsets_k // group_size\n        z_ptrs = zeros_ptr + z_k[:, None] * (N // 8) + (pid_n * (BLOCK_SIZE_N // 8) + tl.arange(0, BLOCK_SIZE_N // 8))[None, :]\n        z_packed = tl.load(z_ptrs, mask=(z_k[:, None] < K // group_size) & masks_bn[None, :])\n\n        z0 = (z_packed >> 0) & 0xF\n        z1 = (z_packed >> 4) & 0xF\n        z2 = (z_packed >> 8) & 0xF\n        z3 = (z_packed >> 12) & 0xF\n        z4 = (z_packed >> 16) & 0xF\n        z5 = (z_packed >> 20) & 0xF\n        z6 = (z_packed >> 24) & 0xF\n        z7 = (z_packed >> 28) & 0xF\n\n        zlow_2_0 = tl.interleave(z0, z2)\n        zlow_2_1 = tl.interleave(z1, z3)\n        zlow_4 = tl.interleave(zlow_2_0, zlow_2_1)\n        zhigh_2_0 = tl.interleave(z4, z6)\n        zhigh_2_1 = tl.interleave(z5, z7)\n        zhigh_4 = tl.interleave(zhigh_2_0, zhigh_2_1)\n        zeros = tl.interleave(zlow_4, zhigh_4)\n\n        s_ptrs = scales_ptr + z_k[:, None] * N + (pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N))[None, :]\n        scales = tl.load(s_ptrs, mask=(z_k[:, None] < K // group_size) & (pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N) < N)[None, :])\n\n        b = (b - zeros) * scales\n        b = b.to(a.dtype)\n\n        # Accumulate results.\n        accumulator = tl.dot(a, b, accumulator, out_dtype=accumulator_dtype)\n\n        a_ptrs += BLOCK_SIZE_K * SPLIT_K\n        b_ptrs += (BLOCK_SIZE_K * SPLIT_K) * (N // 8)\n\n    c = accumulator.to(c_ptr.type.element_ty)\n    offs_cm = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)\n    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)\n    c_ptrs = c_ptr + N * offs_cm[:, None] + offs_cn[None, :]\n    c_mask = (offs_cm[:, None] < M) & (offs_cn[None, :] < N)\n    if SPLIT_K == 1:\n        tl.store(c_ptrs, c, mask=c_mask)\n    else:\n        tl.atomic_add(c_ptrs, c, mask=c_mask)"
    }
